package akogen.fabric.v6;
import java.util.*;import java.util.concurrent.atomic.*;
public final class RelayIntegrationChecks {
 public static void main(String[]args)throws Exception{String channel="akogen/beta/check/"+UUID.randomUUID().toString().replace("-","");AtomicInteger first=new AtomicInteger(),second=new AtomicInteger();MqttLink a=new MqttLink("broker.emqx.io",8883,(t,b)->{try{SyncCodec.State state=SyncCodec.decode(b,"test");if(state.ids.length==1&&state.ids[0]==39)first.incrementAndGet();}catch(Exception e){throw new RuntimeException(e);}}),b=new MqttLink("broker.emqx.io",8883,(t,body)->{try{SyncCodec.State state=SyncCodec.decode(body,"test");if(state.ids.length==1&&state.ids[0]==38)second.incrementAndGet();}catch(Exception e){throw new RuntimeException(e);}});try{a.open();b.open();a.subscriptions(Collections.singleton(channel+"/b"));b.subscriptions(Collections.singleton(channel+"/a"));a.poll();b.poll();String epoch=UUID.randomUUID().toString().replace("-","");a.publish(channel+"/a",SyncCodec.encode("test",epoch,new int[]{38},1,false));b.publish(channel+"/b",SyncCodec.encode("test",epoch,new int[]{39},1,false));long until=System.currentTimeMillis()+12000;while(System.currentTimeMillis()<until&&(first.get()==0||second.get()==0)){a.poll();b.poll();}if(first.get()==0||second.get()==0)throw new AssertionError("Bidirectional relay failed");b.close();b=new MqttLink("broker.emqx.io",8883,(t,body)->second.incrementAndGet());b.open();b.subscriptions(Collections.singleton(channel+"/a"));b.poll();a.publish(channel+"/a",SyncCodec.encode("test",epoch,new int[]{38},2,false));int expected=second.get();until=System.currentTimeMillis()+8000;while(System.currentTimeMillis()<until&&second.get()==expected){a.poll();b.poll();}if(second.get()==expected)throw new AssertionError("Reconnect failed");System.out.println("PASS real trusted-TLS relay: two independent clients, bidirectional cosmetic IDs, reconnect/resubscribe; no retained publications");}finally{a.close();b.close();}}
}
